    static let vtable: UniffiVTableCallbackInterfaceStreamCallbacks = UniffiVTableCallbackInterfaceStreamCallbacks(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceStreamCallbacks.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface StreamCallbacks: handle missing in uniffiFree")
            }
