fileprivate struct FfiConverterSequenceTypeConsoleInfo: FfiConverterRustBuffer {
    typealias SwiftType = [ConsoleInfo]

    public static func write(_ value: [ConsoleInfo], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeConsoleInfo.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [ConsoleInfo] {
        let len: Int32 = try readInt(&buf)
        var seq = [ConsoleInfo]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeConsoleInfo.read(from: &buf))
        }
        return seq
    }
}

